<?php
require dirname(__DIR__).'/issuers_core_support.php';
require APPPATH.'services/CompanyClients.php';
$f=essentialFixture('1.0.2',1);$db=$f->db;$p=$f->prefix;
IssuerCore::reconcile($db,$p);IssuerCore::bindInstallationMaster($db,$p,7);
// Only this isolated synthetic table is replaced to match native client fields.
$db->query("DROP TABLE {$p}clients");
$id=$db->driver()==='sqlite'?'INTEGER PRIMARY KEY AUTOINCREMENT':'INT NOT NULL AUTO_INCREMENT PRIMARY KEY';
$db->query("CREATE TABLE {$p}clients(userid $id,company VARCHAR(191),vat VARCHAR(50),datecreated DATETIME NOT NULL,addedfrom INT NOT NULL DEFAULT 0,active INT NOT NULL DEFAULT 1)");
$db->query("INSERT INTO {$p}clients(userid,company,vat,datecreated) VALUES(9,'Legacy synthetic','529.982.247-25','2026-10-18 00:00:00')");
$db->query("INSERT INTO {$p}issuers_registry(id,legal_name,tax_id,active,settings_json,created_by,created_at,identity_status) VALUES(41,'Synthetic A','12345678000195',1,'{}',7,'2026-10-18 00:00:00','complete'),(82,'Synthetic B','52998224725',1,'{}',7,'2026-10-18 00:00:00','complete')");
$db->query("INSERT INTO {$p}staff VALUES(12,1,0,NULL),(13,1,1,NULL)");
$db->query("INSERT INTO {$p}issuers_staff(issuer_id,staff_id,can_view) VALUES(41,12,1),(82,12,1)");
foreach([41,82] as $issuer)foreach(['view','create','edit','share'] as $cap)$db->query("INSERT INTO {$p}issuers_resource_permissions VALUES(?,12,'customers',?)",[$issuer,$cap]);
if($db->driver()==='mysql'){
    if(!class_exists('CI_Migration')){#[AllowDynamicProperties] class CI_Migration {}}
    require_once APPPATH.'migrations/406_version_406.php';$migration=new Migration_Version_406();$migration->db=$db;$migration->up();$migration->up();
}else{
    $db->query("CREATE TABLE {$p}company_client_requests(request_key varchar(64) PRIMARY KEY,issuer_id int unsigned NOT NULL,actor_id int NOT NULL,input_hash varchar(64) NOT NULL,client_id int NOT NULL,created_at datetime NOT NULL)");
}
$clients=new CompanyClients($db,$p);
$a=$clients->create(41,12,['company'=>'Private synthetic A','vat'=>'111.444.777-35']);
$b=$clients->create(82,12,['company'=>'Private synthetic B']);
essentialCheck($a!==$b,'independent owned customer IDs');
essentialCheck($clients->get(41,12,$a)['company']==='Private synthetic A','A can read its own customer');
essentialCheck($clients->get(82,12,$a)===null && $clients->get(41,12,$b)===null,'direct IDs never cross companies');
essentialCheck($clients->get(41,12,9)===null,'legacy unowned customer not adopted by read');
essentialCheck(count($clients->page(41,12)['items'])===1 && count($clients->page(82,12)['items'])===1,'directory scoped without global counts');
$clients->update(82,12,$b,['company'=>'B changed','vat'=>'12345678000195']);
essentialCheck($clients->get(82,12,$b)['company']==='B changed','B update positive');
essentialCheck($clients->get(41,12,$a)['company']==='Private synthetic A','B edit cannot change A');
essentialThrows(fn()=>$clients->update(82,12,$a,['company'=>'forbidden']),'company_client_access_denied','cross-company mutation denied');
essentialThrows(fn()=>$clients->create(82,12,['company'=>'duplicate','vat'=>'11144477735']),'company_client_identity_conflict','private duplicate handled before creating another identity');
essentialThrows(fn()=>$clients->create(82,12,['company'=>'duplicate legacy','vat'=>'52998224725']),'company_client_identity_conflict','formatted legacy identity conflict is detected');
essentialThrows(fn()=>$clients->create(82,12,['company'=>'overpost','owner_issuer_id'=>41]),'company_client_invalid_input','ownership cannot be supplied through form input');
essentialThrows(fn()=>$clients->get(82,13,$b),'company_client_access_denied','global admin without company membership denied');
$clients->setSharing(41,12,$a,[82]);
$sharedAudit=(int)$db->query("SELECT COUNT(*) n FROM {$p}issuers_audit")->row()->n;
$clients->setSharing(41,12,$a,[82,82]);
essentialCheck((int)$db->query("SELECT COUNT(*) n FROM {$p}issuers_audit")->row()->n===$sharedAudit,'repeated share is idempotent');
essentialCheck($clients->get(82,12,$a)['userid']===$a,'explicit link exposes identity without cloning');
essentialThrows(fn()=>$clients->update(82,12,$a,['company'=>'linked overwrite']),'company_client_access_denied','linked identity not editable by non-owner');
essentialCheck(array_keys($clients->get(82,12,$a))===['userid','company','vat','active','owner_issuer_id'],'projection excludes contacts, payment credentials and finances');
$clients->setSharing(41,12,$a,[]);
essentialCheck($clients->get(82,12,$a)===null,'sharing revocation is effective on next read');
$count=(int)$db->query("SELECT COUNT(*) n FROM {$p}clients")->row()->n;
$db->failOn='INSERT INTO '.$p.'issuers_audit';
essentialThrows(fn()=>$clients->create(82,12,['company'=>'rollback']),'issuer_storage_failed','audit failure aborts entire create');
$db->failOn=null;
essentialCheck((int)$db->query("SELECT COUNT(*) n FROM {$p}clients")->row()->n===$count,'no orphan customer after failed audit');
$db->trans_begin();
essentialThrows(fn()=>$clients->create(82,12,['company'=>'outer']),'issuer_outer_transaction_not_allowed','does not commit caller transaction');
essentialCheck($db->pdo->inTransaction(),'caller transaction still owned by caller');$db->trans_rollback();
$c=$clients->create(82,12,['company'=>'Second B']);
$page=$clients->page(82,12,0,1);essentialCheck(count($page['items'])===1 && $page['next']===$b,'keyset first page');
$page=$clients->page(82,12,$page['next'],1);essentialCheck(count($page['items'])===1 && $page['items'][0]['userid']===$c && $page['next']===null,'keyset next page');
$db->query("UPDATE {$p}issuers_staff SET can_view=0 WHERE issuer_id=82 AND staff_id=12");
essentialThrows(fn()=>$clients->get(82,12,$b),'company_client_access_denied','membership revocation cannot reuse earlier grant');
essentialCheck((int)$db->query("SELECT COUNT(*) n FROM {$p}invoices")->row()->n===1,'customer operations do not copy or create finance');
essentialCheck($db->query("SELECT company FROM {$p}clients WHERE userid=9")->row()->company==='Legacy synthetic','legacy identity preserved');
$db->query("UPDATE {$p}issuers_staff SET can_view=1 WHERE issuer_id=82 AND staff_id=12");
$db->query("DELETE FROM {$p}issuers_resource_permissions WHERE issuer_id=82 AND staff_id=12 AND feature='customers' AND capability='edit'");
essentialThrows(fn()=>$clients->update(82,12,$b,['company'=>'revoked']),'company_client_access_denied','permission revocation stops edits despite membership');
$db->query("DELETE FROM {$p}issuers_resource_permissions WHERE issuer_id=82 AND staff_id=12 AND feature='customers' AND capability='create'");
essentialThrows(fn()=>$clients->setSharing(41,12,$a,[82]),'company_client_access_denied','destination permission required before sharing');
essentialCheck($clients->get(82,12,$a)===null,'denied share leaves no link');
essentialThrows(fn()=>$clients->setSharing(82,12,$a,[41]),'company_client_access_denied','recipient cannot reshare another owner identity');
$db->query("UPDATE {$p}issuers_registry SET active=0 WHERE id=82");
essentialThrows(fn()=>$clients->page(82,12),'company_client_access_denied','inactive company cannot list identities');
essentialThrows(fn()=>$clients->page(41,12,0,1000),'company_client_invalid_page','page size bounded');
essentialThrows(fn()=>$clients->create(41,12,['company'=>'Invalid VAT','vat'=>'00000000000']),'issuer_invalid_tax_id','invalid taxpayer identifier rejected');
$audit=json_encode($db->query("SELECT event,metadata_json FROM {$p}issuers_audit")->result_array());
essentialCheck(!str_contains($audit,'Private synthetic')&&!str_contains($audit,'11144477735'),'audit excludes private names and taxpayer identifiers');
echo 'Company private customers: '.$GLOBALS['essentialChecks'].' checks passed.'.PHP_EOL;

$key=str_repeat('a',64);$input=['company'=>'Idempotent synthetic'];
$id=$clients->create(41,12,$input,$key);$count=(int)$db->query("SELECT COUNT(*) n FROM {$p}clients")->row()->n;
essentialCheck($clients->create(41,12,$input,$key)===$id,'durable create retry returns original ID');
essentialCheck((int)$db->query("SELECT COUNT(*) n FROM {$p}clients")->row()->n===$count,'retry does not duplicate customer without taxpayer identifier');
essentialThrows(fn()=>$clients->create(41,12,['company'=>'changed'],$key),'company_client_request_conflict','same request key cannot adopt different input');
$db->query("UPDATE {$p}issuers_registry SET active=1 WHERE id=82");
essentialThrows(fn()=>$clients->create(82,7,$input,$key),'company_client_request_conflict','receipt cannot be replayed in another company');
$detail=$clients->details(41,12,$id);$revision=$detail['revision'];
$clients->update(41,12,$id,['company'=>'New revision'],$revision);
essentialThrows(fn()=>$clients->update(41,12,$id,['company'=>'Stale replacement'],$revision),'company_client_stale','stale edit rejected under owner lock');
essentialThrows(fn()=>$clients->setSharing(41,12,$id,[],$revision),'company_client_stale','stale sharing cannot overwrite current identity state');
$revision=$clients->details(41,12,$id)['revision'];$clients->setSharing(41,7,$id,[82],$revision);
essentialCheck($clients->details(82,7,$id)['targets']===[] && $clients->details(82,7,$id)['revision']===null,'recipient does not enumerate other sharing recipients or owner revision');
$db->query("UPDATE {$p}issuers_staff SET can_view=0 WHERE issuer_id=82 AND staff_id=12");
$clients->setSharing(41,12,$id,[],$clients->details(41,12,$id)['revision']);
essentialCheck($clients->get(82,7,$id)===null,'owner can revoke after losing destination membership');
essentialCheck(count($clients->page(41,12,0,50,'New revision')['items'])===1,'search returns only visible identities');
essentialCheck($clients->page(41,12,0,50,'%')['items']===[],'search wildcard is a literal');
$db->failOn='INSERT INTO '.$p.'company_client_requests';
essentialThrows(fn()=>$clients->create(41,12,['company'=>'Receipt rollback'],str_repeat('b',64)),'issuer_storage_failed','failed durable receipt rolls back customer and audit');$db->failOn=null;
essentialCheck((int)$db->query("SELECT COUNT(*) n FROM {$p}clients")->row()->n===$count,'no orphan on receipt failure');
if($db->driver()==='mysql'){
    $db->query("ALTER TABLE {$p}company_client_requests DROP PRIMARY KEY, ADD PRIMARY KEY(request_key(32))");
    essentialThrows(fn()=>CompanyClientRequestSchema::ensure($db,$p),'company_client_request_schema_invalid','prefix receipt index rejected');
}
echo 'Company customer directory and receipts: '.$GLOBALS['essentialChecks'].' checks passed.'.PHP_EOL;
